{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C17"],
      "claim": "Loteprednol etabonate, a soft corticosteroid ester, showed very low oral bioavailability after a 40-mg oral dose, supporting that soft-steroid modifications can drive F below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C49"],
      "claim": "Mometasone, a lipophilic halogenated/ester corticosteroid, has <1% oral bioavailability due to extensive first-pass metabolism, analogous to the acetal soft-steroid scaffold of the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Prednisolone, the closest structural analogue by similarity, has 72% systemic availability after oral administration, indicating the corticosteroid core can be well absorbed when no acetal/soft-steroid modification is present.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C37"],
      "claim": "Deflazacort, a cyclic prodrug corticosteroid, has 68% absolute oral bioavailability, showing that some prodrug modifications do not necessarily reduce F below 20%.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C53"],
      "claim": "Beclomethasone 17-monopropionate, an active metabolite of a soft steroid, has 41% oral bioavailability, providing a counterexample where a soft-steroid metabolite still exceeds the 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a 16,17-cyclic acetal corticosteroid (desisobutyryl-ciclesonide-like soft steroid). Although simple corticosteroids such as prednisolone and deflazacort show high oral bioavailability, the acetal/soft-steroid analogues with low oral bioavailability (loteprednol etabonate, mometasone) and the known first-pass liability of ciclesonide-type acetals support F <20%. The high-F analogues lack the key acetal modification and are less transferable for this endpoint.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for desisobutyryl-ciclesonide is available in the evidence set.",
    "Budesonide, the closest 16,17-acetal corticosteroid analogue with known low oral bioavailability, is not included.",
    "Uncertainty remains about gastrointestinal stability of the cyclohexyl acetal and the extent of first-pass metabolism of the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

